331: // HandleStop parses the raw JSON payload and handles the Stop event within the execution budget.
332: // It returns a standard JSON object string ("{}") on completion or no-op skip.
333: // When the v2 spike is active and a continue is triggered, it returns
334: // {"decision": "continue", "reason": "<request>"} to instruct Antigravity to
335: // resume the agent.
336: // By contract, it strictly fails open on malformed JSON or event handler errors by returning "{}".
337: func HandleStop(ctx context.Context, rawPayload []byte, opts ...HookOption) ([]byte, error) {
338: 	if ctx == nil {
339: 		ctx = context.Background()
340: 	}
341: 
342: 	defer func() {
343: 		if r := recover(); r != nil {
344: 			fmt.Fprintf(os.Stderr, "[repo-memory] Stop panic recovered: %v\n", r)
345: 		}
346: 	}()
347: 
348: 	var payload StopPayload
349: 	if len(rawPayload) > 0 && strings.TrimSpace(string(rawPayload)) != "" {
350: 		if err := json.Unmarshal(rawPayload, &payload); err != nil {
351: 			fmt.Fprintf(os.Stderr, "[repo-memory] parsing Stop payload JSON error: %v (failing open)\n", err)
352: 			return []byte("{}"), nil
353: 		}
354: 	}
355: 	payload.Normalize()
356: 
357: 	result, err := HandleStopEvent(ctx, &payload, opts...)
358: 	if err != nil {
359: 		fmt.Fprintf(os.Stderr, "[repo-memory] Stop event error: %v (failing open)\n", err)
360: 		return []byte("{}"), nil
361: 	}
362: 
363: 	// V2 spike: return continue response if the gate triggered
364: 	if result != nil && result.V2Continue {
365: 		resp := map[string]interface{}{
366: 			"decision": "continue",
367: 			"reason":   result.V2ContinueRequest,
368: 		}
369: 		out, err := json.Marshal(resp)
370: 		if err != nil {
371: 			return []byte("{}"), nil
372: 		}
373: 		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Stop continue triggered for %s (executionNum=0)\n", payload.ConversationID)
374: 		return out, nil
375: 	}
376: 
377: 	return []byte("{}"), nil
378: }
