380: // HandleStopEvent executes the complete Stop hook pipeline:
381: // 1. Enforces execution budget (≤ 200ms)
382: // 2. Evaluates kill-switch checks (REPO_MEMORY_DISABLED, machine config, repo config)
383: // 3. Evaluates REPO_MEMORY_HOUSEKEEPING guard (skipping housekeeping runs)
384: // 4. Evaluates enrolment checks (verifying the workspace is enrolled in registry)
385: // 5. Creates and writes a durable capture spool entry
386: // 6. Performs incremental transcript copying into queue/ with cursor state tracking
387: func HandleStopEvent(ctx context.Context, payload *StopPayload, opts ...HookOption) (*StopResult, error) {
388: 	start := time.Now()
389: 
390: 	opt := HookOptions{
391: 		Timeout: DefaultHookBudget,
392: 	}
393: 	for _, fn := range opts {
394: 		fn(&opt)
395: 	}
396: 
397: 	// 1. Budget enforcement (≤ 200ms)
398: 	budget := opt.Timeout
399: 	if budget <= 0 {
400: 		budget = DefaultHookBudget
401: 	}
402: 	if ctx == nil {
403: 		ctx = context.Background()
404: 	}
405: 	var cancel context.CancelFunc
406: 	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
407: 		ctx, cancel = context.WithTimeout(ctx, budget)
408: 		defer cancel()
409: 	}
410: 
411: 	// 2. Kill-switch check (Step A: REPO_MEMORY_DISABLED env var)
412: 	if os.Getenv("REPO_MEMORY_DISABLED") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_DISABLED"), "true") {
413: 		return &StopResult{
414: 			Skipped:  true,
415: 			Reason:   "kill-switch active (REPO_MEMORY_DISABLED)",
416: 			Duration: time.Since(start),
417: 		}, nil
418: 	}
419: 
420: 	// 3. REPO_MEMORY_HOUSEKEEPING guard (Step B: skip housekeeping runs per SPEC §6.2 / E07)
421: 	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_HOUSEKEEPING"), "true") {
422: 		return &StopResult{
423: 			Skipped:  true,
424: 			Reason:   "housekeeping run skipped (REPO_MEMORY_HOUSEKEEPING)",
425: 			Duration: time.Since(start),
426: 		}, nil
427: 	}
428: 
429: 	dataDir := opt.DataDir
430: 	if dataDir == "" {
431: 		dataDir = config.DataDir()
432: 	}
433: 
434: 	// 2. Kill-switch check (Step C: machine configuration enabled)
435: 	machCfg, err := config.LoadMachineConfig(dataDir)
436: 	if err != nil {
437: 		return nil, fmt.Errorf("loading machine config: %w", err)
438: 	}
439: 	if !machCfg.Enabled {
440: 		return &StopResult{
441: 			Skipped:  true,
442: 			Reason:   "kill-switch active (machine config disabled)",
443: 			Duration: time.Since(start),
444: 		}, nil
445: 	}
446: 
447: 	// Determine candidate workspace
448: 	workspace := opt.WorkspaceOverride
449: 	if workspace == "" && len(payload.WorkspacePaths) > 0 && payload.WorkspacePaths[0] != "" {
450: 		workspace = payload.WorkspacePaths[0]
451: 	}
452: 	if workspace == "" && payload.TranscriptPath != "" {
453: 		if root, err := gitops.FindRepoRoot(filepath.Dir(payload.TranscriptPath)); err == nil {
454: 			workspace = root
455: 		}
456: 	}
457: 	var convSummary *ConversationSummary
458: 	if (workspace == "" || payload.ParentConversationID == "") && payload.ConversationID != "" && (opt.AppDBPath != "" || opt.CliDBPath != "") {
459: 		var attrOpts []AttributionOption
460: 		if opt.AppDBPath != "" {
461: 			attrOpts = append(attrOpts, WithAppDBPath(opt.AppDBPath))
462: 		}
463: 		if opt.CliDBPath != "" {
464: 			attrOpts = append(attrOpts, WithCliDBPath(opt.CliDBPath))
465: 		}
466: 		convSummary, _ = LookupConversationSummary(payload.ConversationID, attrOpts...)
467: 		if workspace == "" && convSummary != nil && len(convSummary.WorkspacePaths) > 0 {
468: 			workspace = convSummary.WorkspacePaths[0]
469: 		}
470: 	}
471: 	if workspace == "" {
472: 		if wd, err := os.Getwd(); err == nil {
473: 			workspace = wd
474: 		}
475: 	}
476: 
477: 	// Additional housekeeping path guard: directory matching runs/<repo-id>
478: 	if isHousekeepingPath(workspace) {
479: 		return &StopResult{
480: 			Skipped:  true,
481: 			Reason:   "housekeeping directory skipped (runs/ path)",
482: 			Duration: time.Since(start),
483: 		}, nil
484: 	}
485: 
486: 	// 4. Enrolment check (Step D: verify repository enrolment in registry.json)
487: 	entry, found, err := config.FindRegistryEntry(dataDir, workspace)
488: 	if err != nil {
489: 		return nil, fmt.Errorf("querying registry: %w", err)
490: 	}
491: 	if !found || entry == nil {
492: 		return &StopResult{
493: 			Skipped:  true,
494: 			Reason:   "workspace not enrolled in registry",
495: 			Duration: time.Since(start),
496: 		}, nil
497: 	}
498: 
499: 	// 2. Kill-switch check (Step E: repository config enabled)
500: 	repoCfg, err := config.LoadRepoConfig(entry.RootPath)
501: 	if err != nil {
502: 		return nil, fmt.Errorf("loading repo config: %w", err)
503: 	}
504: 	if !repoCfg.IsEnabled() {
505: 		return &StopResult{
506: 			Skipped:  true,
507: 			Reason:   "kill-switch active (repo config disabled)",
508: 			Duration: time.Since(start),
509: 		}, nil
510: 	}
511: 
512: 	repoID := entry.RepoID
513: 	if repoID == "" {
514: 		repoID, err = gitops.GenerateRepoID(entry.RootPath)
515: 		if err != nil {
516: 			return nil, fmt.Errorf("generating repo ID: %w", err)
517: 		}
518: 	}
519: 	repoRoot := entry.RootPath
520: 
521: 	// Ensure destination directory structure exists under <data-dir>/<repo-id>/
522: 	if err := config.EnsureDataDirLayout(dataDir, repoID); err != nil {
523: 		return nil, fmt.Errorf("ensuring data dir layout: %w", err)
524: 	}
525: 
526: 	// Query Git branch and HEAD commit (bounded by 50ms context timeout to preserve budget)
527: 	gitCtx, gitCancel := context.WithTimeout(ctx, 50*time.Millisecond)
528: 	branch, _ := gitops.GetCurrentBranchWithContext(gitCtx, repoRoot)
529: 	head, _ := gitops.GetHeadCommitWithContext(gitCtx, repoRoot)
530: 	gitCancel()
531: 
532: 	convID := payload.ConversationID
533: 	if convID == "" {
534: 		return &StopResult{
535: 			Skipped:  true,
536: 			Reason:   "conversation ID empty; no session to capture",
